package com.reviewflow.web;
import com.reviewflow.domain.Business;import com.reviewflow.repo.BusinessRepository;import com.reviewflow.service.AnalyticsService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/analytics") public class AnalyticsController {private final BusinessRepository businesses;private final AnalyticsService analytics;public AnalyticsController(BusinessRepository b,AnalyticsService a){businesses=b;analytics=a;}private Business business(Authentication a){return businesses.findFirstByUserId((UUID)a.getPrincipal()).orElseThrow();}private LocalDate start(String s){return s==null?LocalDate.now().minusDays(29):LocalDate.parse(s);}private LocalDate end(String s){return s==null?LocalDate.now():LocalDate.parse(s);}@GetMapping("/overview")public Object overview(@RequestParam(required=false)String start,@RequestParam(required=false)String end,Authentication a){return analytics.overview(business(a),start(start),end(end));}@GetMapping("/reviews")public Object reviews(@RequestParam(required=false)String start,@RequestParam(required=false)String end,Authentication a){return analytics.reviewPoints(business(a),start(start),end(end));}@GetMapping("/rating")public Object rating(@RequestParam(required=false)String start,@RequestParam(required=false)String end,Authentication a){return analytics.ratingPoints(business(a),start(start),end(end));}@GetMapping("/scans")public Object scans(@RequestParam(required=false)String start,@RequestParam(required=false)String end,Authentication a){return analytics.scanPoints(business(a),start(start),end(end));}}
